<?php
if (!defined('ABSPATH')) { exit; }
require_once get_theme_file_path('/inc/client-profile.php');
require_once get_theme_file_path('/inc/creditos.php');
function legacyx_theme_setup(){add_theme_support('title-tag');add_theme_support('post-thumbnails');add_theme_support('html5',array('search-form','comment-form','comment-list','gallery','caption','style','script'));register_nav_menus(array('primary'=>__('Primary Navigation','legacy-x-firm')));}add_action('after_setup_theme','legacyx_theme_setup');
function legacyx_enqueue_assets(){$css=get_stylesheet_directory().'/style.css';$polish=get_stylesheet_directory().'/assets/css/polish.css';$assessment=get_stylesheet_directory().'/assets/css/assessment.css';wp_enqueue_style('legacyx-style',get_stylesheet_uri(),array(),file_exists($css)?filemtime($css):'1.0.0');wp_enqueue_style('legacyx-polish',get_stylesheet_directory_uri().'/assets/css/polish.css',array('legacyx-style'),file_exists($polish)?filemtime($polish):'1.0.0');if(is_page('executive-assessment'))wp_enqueue_style('legacyx-assessment',get_stylesheet_directory_uri().'/assets/css/assessment.css',array('legacyx-polish'),file_exists($assessment)?filemtime($assessment):'1.0.0');}add_action('wp_enqueue_scripts','legacyx_enqueue_assets');
function legacyx_client_portal_template($template){if(is_page('client-portal')){$f=get_theme_file_path('/client-portal.php');if(file_exists($f))return $f;}if(is_page('executive-assessment')){$f=get_theme_file_path('/executive-assessment.php');if(file_exists($f))return $f;}if(is_page('credit-capital-center')){$f=get_theme_file_path('/credit-capital-center.php');if(file_exists($f))return $f;}return $template;}add_filter('template_include','legacyx_client_portal_template',99);
function legacyx_body_classes($classes){if(is_page('client-portal'))$classes[]='legacyx-client-portal-page';if(is_page('executive-assessment'))$classes[]='legacyx-executive-assessment-page';if(is_page('credit-capital-center'))$classes[]='legacyx-credit-center-page';return $classes;}add_filter('body_class','legacyx_body_classes');
function legacyx_ensure_system_pages(){foreach(array('executive-assessment'=>'Executive Assessment','credit-capital-center'=>'Credit & Capital Center') as $slug=>$title){if(!get_page_by_path($slug))wp_insert_post(array('post_title'=>$title,'post_name'=>$slug,'post_status'=>'publish','post_type'=>'page','post_content'=>''));}}add_action('init','legacyx_ensure_system_pages',20);
function legacyx_register_assessment_type(){register_post_type('legacyx_assessment',array('labels'=>array('name'=>'Executive Assessments','singular_name'=>'Executive Assessment','menu_name'=>'Assessments','all_items'=>'All Assessments','view_item'=>'Review Assessment'),'public'=>false,'show_ui'=>true,'show_in_menu'=>true,'menu_icon'=>'dashicons-clipboard','supports'=>array('title'),'capability_type'=>'post','map_meta_cap'=>true));}add_action('init','legacyx_register_assessment_type');
function legacyx_clean_assessment_array($v){if(!is_array($v))return array();return array_values(array_filter(array_map('sanitize_text_field',$v)));}
function legacyx_submit_assessment(){if(!isset($_POST['legacyx_assessment_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['legacyx_assessment_nonce'])),'legacyx_assessment_submit'))wp_die('Security validation failed.','Legacy X Firm',array('response'=>403));$n=isset($_POST['full_name'])?sanitize_text_field(wp_unslash($_POST['full_name'])):'';$e=isset($_POST['email'])?sanitize_email(wp_unslash($_POST['email'])):'';$t=isset($_POST['timeline'])?sanitize_text_field(wp_unslash($_POST['timeline'])):'';$o=isset($_POST['objective'])?sanitize_textarea_field(wp_unslash($_POST['objective'])):'';if(!$n||!is_email($e)||!$t||!$o||empty($_POST['consent']))wp_die('Please complete all required assessment fields.','Legacy X Firm',array('response'=>400));$aid=wp_insert_post(array('post_type'=>'legacyx_assessment','post_status'=>'private','post_title'=>$n.' — '.current_time('Y-m-d H:i')));if(is_wp_error($aid)||!$aid)wp_die('We could not save your assessment.','Legacy X Firm',array('response'=>500));$f=array('full_name'=>$n,'email'=>$e,'phone'=>sanitize_text_field(wp_unslash($_POST['phone']??'')),'location'=>sanitize_text_field(wp_unslash($_POST['location']??'')),'role'=>sanitize_text_field(wp_unslash($_POST['role']??'')),'business_name'=>sanitize_text_field(wp_unslash($_POST['business_name']??'')),'business_stage'=>sanitize_text_field(wp_unslash($_POST['business_stage']??'')),'revenue'=>sanitize_text_field(wp_unslash($_POST['revenue']??'')),'capital_need'=>sanitize_text_field(wp_unslash($_POST['capital_need']??'')),'timeline'=>$t,'objective'=>$o,'obstacle'=>sanitize_textarea_field(wp_unslash($_POST['obstacle']??'')),'engagement'=>sanitize_text_field(wp_unslash($_POST['engagement']??'')),'source'=>sanitize_text_field(wp_unslash($_POST['source']??'')),'priorities'=>legacyx_clean_assessment_array(isset($_POST['priorities'])?wp_unslash($_POST['priorities']):array()),'consent'=>1,'submitted_at'=>current_time('mysql'));foreach($f as $k=>$v)update_post_meta($aid,'_legacyx_'.$k,$v);$parts=preg_split('/\s+/',trim($n),2);$cid=wp_insert_post(array('post_type'=>'legacyx_client','post_status'=>'publish','post_title'=>$n.($f['business_name']?' — '.$f['business_name']:'')));if(!is_wp_error($cid)&&$cid){$m=array('first_name'=>$parts[0]??'','last_name'=>$parts[1]??'','email'=>$e,'phone'=>$f['phone'],'business_name'=>$f['business_name'],'annual_revenue'=>$f['revenue'],'capital_goal'=>$f['capital_need'],'status'=>'Assessment','service_level'=>$f['engagement'],'source'=>$f['source']?:'Executive Assessment','assessment_id'=>$aid,'ownership_notes'=>'Primary role: '.$f['role']."\nBusiness stage: ".$f['business_stage'],'financial_notes'=>'Primary objective: '.$o."\nCurrent obstacle: ".$f['obstacle']."\nTimeline: ".$t."\nPriorities: ".implode(', ',$f['priorities']));foreach($m as $k=>$v)update_post_meta($cid,'_legacyx_'.$k,$v);update_post_meta($cid,'_legacyx_client_id',legacyx_client_id($cid));update_post_meta($aid,'_legacyx_client_profile_id',$cid);}wp_mail(get_option('admin_email'),'New Legacy X Firm Executive Assessment — '.$n,"New Executive Assessment submitted.\nName: {$n}\nEmail: {$e}\nTimeline: {$t}");wp_safe_redirect(add_query_arg('submitted','1',home_url('/executive-assessment/')));exit;}add_action('admin_post_nopriv_legacyx_submit_assessment','legacyx_submit_assessment');add_action('admin_post_legacyx_submit_assessment','legacyx_submit_assessment');
function legacyx_assessment_columns($c){return array('cb'=>$c['cb']??'<input type="checkbox" />','title'=>'Principal','business'=>'Business','priority'=>'Primary Priorities','timeline'=>'Timeline','date'=>'Received');}add_filter('manage_legacyx_assessment_posts_columns','legacyx_assessment_columns');function legacyx_assessment_column_content($col,$id){if($col==='business')echo esc_html(get_post_meta($id,'_legacyx_business_name',true));if($col==='priority'){$p=get_post_meta($id,'_legacyx_priorities',true);echo esc_html(is_array($p)?implode(', ',array_slice($p,0,2)):'');}if($col==='timeline')echo esc_html(get_post_meta($id,'_legacyx_timeline',true));}add_action('manage_legacyx_assessment_posts_custom_column','legacyx_assessment_column_content',10,2);
function legacyx_assessment_details_box(){add_meta_box('legacyx-assessment-details','Executive Assessment Details','legacyx_render_assessment_details','legacyx_assessment','normal','high');}add_action('add_meta_boxes','legacyx_assessment_details_box');function legacyx_render_assessment_details($post){$labels=array('full_name'=>'Full Name','email'=>'Email','phone'=>'Phone','location'=>'Location','role'=>'Primary Role','business_name'=>'Business / Organization','business_stage'=>'Business Stage','revenue'=>'Approx. Annual Revenue','capital_need'=>'Capital Need / Objective','timeline'=>'Timeline','objective'=>'Primary Outcome','obstacle'=>'Current Obstacle','engagement'=>'Preferred Engagement','source'=>'Referral Source','priorities'=>'Strategic Priorities','submitted_at'=>'Submitted At');echo '<div style="display:grid;grid-template-columns:220px 1fr;border:1px solid #ddd">';foreach($labels as $k=>$l){$v=get_post_meta($post->ID,'_legacyx_'.$k,true);if(is_array($v))$v=implode(', ',$v);echo '<div style="padding:10px;font-weight:700;background:#f6f6f6;border-bottom:1px solid #ddd">'.esc_html($l).'</div><div style="padding:10px;border-bottom:1px solid #ddd">'.nl2br(esc_html($v)).'</div>';}$cid=absint(get_post_meta($post->ID,'_legacyx_client_profile_id',true));if($cid)echo '<div style="padding:10px;font-weight:700">Client Profile</div><div style="padding:10px"><a href="'.esc_url(get_edit_post_link($cid)).'">Open Universal Client Profile</a></div>';echo '</div>';}
function legacyx_disable_emojis(){remove_action('wp_head','print_emoji_detection_script',7);remove_action('wp_print_styles','print_emoji_styles');}add_action('init','legacyx_disable_emojis');remove_action('wp_head','rsd_link');remove_action('wp_head','wlwmanifest_link');remove_action('wp_head','wp_generator');remove_action('wp_head','wp_shortlink_wp_head');remove_action('wp_head','wp_oembed_add_discovery_links');function legacyx_remove_embed(){if(!is_admin())wp_deregister_script('wp-embed');}add_action('wp_footer','legacyx_remove_embed',1);function legacyx_remove_dashicons(){if(!is_user_logged_in())wp_dequeue_style('dashicons');}add_action('wp_enqueue_scripts','legacyx_remove_dashicons',100);function legacyx_async_images($a){if(!is_admin()&&empty($a['decoding']))$a['decoding']='async';return $a;}add_filter('wp_get_attachment_image_attributes','legacyx_async_images',20);
